const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const journey=document.querySelector('.history-journey');
if(journey&&!document.querySelector('#history-world')){
 const stations=[...journey.querySelectorAll('.history-station')],svg=journey.querySelector('.history-track'),paths=[...svg.querySelectorAll('path')],train=journey.querySelector('.history-train'),years=[...document.querySelectorAll('[data-year-target]')],current=document.querySelector('#history-current');
 let length=0,points=[],progress=0,target=0,pending=false,animating=false,active=-1;
 function draw(){const width=journey.clientWidth,height=journey.scrollHeight,mobile=innerWidth<=650,x=mobile?28:width/2;svg.setAttribute('viewBox',`0 0 ${width} ${height}`);svg.setAttribute('height',String(height));points=stations.map(s=>({x,y:s.offsetTop+(mobile?60:63)}));let d=`M ${x} 0`;let y=0;for(let i=0;i<points.length;i++){const p=points[i],bend=mobile?6:14;d+=` C ${x+(i%2?bend:-bend)} ${y+(p.y-y)*.35}, ${x+(i%2?-bend:bend)} ${y+(p.y-y)*.7}, ${x} ${p.y}`;y=p.y}d+=` L ${x} ${height-35}`;paths.forEach(p=>p.setAttribute('d',d));svg.querySelector('.track-left').setAttribute('transform',`translate(${mobile?-10:-12} 0)`);svg.querySelector('.track-right').setAttribute('transform',`translate(${mobile?10:12} 0)`);length=paths[0].getTotalLength();const trace=svg.querySelector('.track-progress');trace.style.strokeDasharray=String(length);onScroll()}
 function distanceForY(y){let a=0,b=length;for(let i=0;i<13;i++){const m=(a+b)/2;if(paths[0].getPointAtLength(m).y<y)a=m;else b=m}return (a+b)/2}
 function updateTrain(){animating=false;progress=reduced?target:progress+(target-progress)*.17;const point=paths[0].getPointAtLength(progress),next=paths[0].getPointAtLength(Math.min(length,progress+4)),angle=Math.atan2(next.y-point.y,next.x-point.x)*180/Math.PI-90,mobile=innerWidth<=650;train.style.transform=`translate3d(${point.x-(mobile?20:23)}px,${point.y-(mobile?57:65)}px,0) rotate(${angle}deg)`;svg.querySelector('.track-progress').style.strokeDashoffset=String(length-progress);if(!reduced&&Math.abs(progress-target)>.3){animating=true;requestAnimationFrame(updateTrain)}}
 function onScroll(){pending=false;if(!length)return;const r=journey.getBoundingClientRect(),y=Math.max(0,Math.min(journey.scrollHeight-40,innerHeight*.48-r.top));target=distanceForY(y);let index=0;for(let i=0;i<points.length;i++)if(y>=points[i].y-90)index=i;if(index!==active){active=index;stations.forEach((s,i)=>{s.classList.toggle('is-active',i===active);s.classList.toggle('is-passed',i<active)});years.forEach((b,i)=>{b.classList.toggle('is-current',i===active);b.setAttribute('aria-current',i===active?'step':'false')});if(current)current.textContent=stations[active]?.dataset.year||'';const bar=document.querySelector('.history-years'),button=years[active];if(bar&&button)bar.scrollTo({left:button.offsetLeft-bar.offsetLeft-bar.clientWidth/2+button.clientWidth/2,behavior:reduced?'instant':'smooth'})}if(!animating){animating=true;requestAnimationFrame(updateTrain)}}
 addEventListener('scroll',()=>{if(!pending){pending=true;requestAnimationFrame(onScroll)}},{passive:true});new ResizeObserver(draw).observe(journey);document.fonts.ready.then(draw);years.forEach(button=>button.addEventListener('click',()=>{const node=document.getElementById(button.dataset.yearTarget);node?.scrollIntoView({behavior:reduced?'instant':'smooth',block:'start'});node?.querySelector('h2')?.focus({preventScroll:true})}));draw();
}
if(!reduced){
 document.documentElement.classList.add('chapter-motion-ready');const reveal=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){e.target.classList.add('chapter-visible');reveal.unobserve(e.target)}},{threshold:.035,rootMargin:'0px 0px 25px 0px'});
 document.querySelectorAll('.source-body h2,.source-body .chapter-lead,.source-body .table-scroll,.source-body .chapter-destination,.source-body .card-board,.source-body .page-card,.source-body .official-action').forEach(node=>{if(node.closest('.history-journey')||node.closest('.history-sticky'))return;node.classList.add('chapter-reveal');reveal.observe(node)});
 if(matchMedia('(hover:hover)').matches)document.querySelectorAll('.chapter-visual').forEach(art=>{art.addEventListener('pointermove',e=>{const r=art.getBoundingClientRect();art.classList.add('is-hovering');art.style.setProperty('--art-x',`${(e.clientX-r.left-r.width/2)/35}px`);art.style.setProperty('--art-y',`${(e.clientY-r.top-r.height/2)/35}px`)});art.addEventListener('pointerleave',()=>{art.classList.remove('is-hovering');art.style.setProperty('--art-x','0px');art.style.setProperty('--art-y','0px')})});
}
document.querySelectorAll('.chapter-picker nav a').forEach(a=>a.addEventListener('click',()=>a.closest('details').open=false));
